-- =============================================================================
-- Migration V10: Create Payments table (Module Payment)
-- =============================================================================

CREATE TABLE IF NOT EXISTS "payments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "payment_method" varchar(50) NOT NULL,
  "payment_type" varchar(50) NOT NULL,
  "amount" decimal(12,2) NOT NULL,
  "status" varchar(50) NOT NULL DEFAULT 'PENDING',
  "transaction_code" varchar(255),
  "payment_time" timestamp,
  "note" text,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_payments_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_payments_amount CHECK (amount >= 0),
  CONSTRAINT chk_payments_method CHECK (payment_method IN ('CASH', 'BANK_TRANSFER', 'CARD', 'E_WALLET')),
  CONSTRAINT chk_payments_type CHECK (payment_type IN ('DEPOSIT', 'PARTIAL', 'FINAL', 'REFUND')),
  CONSTRAINT chk_payments_status CHECK (status IN ('PENDING', 'SUCCESS', 'FAILED', 'CANCELLED'))
);

CREATE INDEX IF NOT EXISTS idx_payments_booking_id ON "payments" ("booking_id");
CREATE INDEX IF NOT EXISTS idx_payments_status ON "payments" ("status");
CREATE INDEX IF NOT EXISTS idx_payments_transaction_code ON "payments" ("transaction_code");
